'use client';
import { useEffect, useRef, useState } from 'react';
import { COVER_PHOTO } from '@/lib/projects';

interface HeroProps {
  coverPhoto: string;
}

export function Hero({ coverPhoto }: HeroProps) {
  const parallaxRef = useRef<HTMLDivElement>(null);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const onMouse = (e: MouseEvent) => {
      setMousePos({
        x: (e.clientX / window.innerWidth - 0.5) * 20,
        y: (e.clientY / window.innerHeight - 0.5) * 10,
      });
    };
    window.addEventListener('mousemove', onMouse);
    return () => window.removeEventListener('mousemove', onMouse);
  }, []);

  return (
    <>
      {/* ── HERO ── */}
      <section
        style={{
          minHeight: '100vh',
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          position: 'relative',
          overflow: 'hidden',
        }}
      >
        {/* Left — text */}
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'flex-end',
            padding: '8rem 4rem 5rem 4rem',
            position: 'relative',
            zIndex: 2,
          }}
        >
          {/* Index tag */}
          <div
            style={{
              position: 'absolute',
              top: '7rem',
              left: '4rem',
              display: 'flex',
              flexDirection: 'column',
              gap: '0.25rem',
            }}
          >
            <span className="mono" style={{ color: 'var(--gray-500)', fontSize: '0.6rem' }}>
              Portfolio
            </span>
            <span className="mono" style={{ color: 'var(--gray-500)', fontSize: '0.6rem' }}>
              2024 — 2026
            </span>
          </div>

          {/* Headline */}
          <div style={{ marginBottom: '2rem' }}>
            <div className="hero-title-clip">
              <h1
                className="hero-title-inner"
                style={{
                  fontFamily: 'var(--font-display)',
                  fontWeight: 300,
                  fontSize: 'clamp(3.5rem, 6vw, 7rem)',
                  lineHeight: 0.95,
                  letterSpacing: '-0.03em',
                  color: 'var(--black)',
                }}
              >
                Ayden
              </h1>
            </div>
            <div className="hero-title-clip">
              <h1
                className="hero-title-inner"
                style={{
                  fontFamily: 'var(--font-display)',
                  fontWeight: 300,
                  fontStyle: 'italic',
                  fontSize: 'clamp(3.5rem, 6vw, 7rem)',
                  lineHeight: 0.95,
                  letterSpacing: '-0.03em',
                  color: 'var(--black)',
                }}
              >
                Pettiette
              </h1>
            </div>
          </div>

          {/* Divider */}
          <div className="draw-line" style={{ marginBottom: '2rem', maxWidth: '120px' }} />

          {/* Sub */}
          <div
            className="hero-title-inner"
            style={{
              animationDelay: '0.7s',
              opacity: 0,
              maxWidth: '320px',
            }}
          >
            <p
              style={{
                fontFamily: 'var(--font-display)',
                fontWeight: 300,
                fontSize: '1.1rem',
                lineHeight: 1.6,
                color: 'var(--gray-700)',
                marginBottom: '2rem',
              }}
            >
              Architectural design student — exploring form, space, and material through built and speculative work.
            </p>
            <a
              href="#work"
              data-hover
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '0.75rem',
                fontFamily: 'var(--font-mono)',
                fontSize: '0.65rem',
                letterSpacing: '0.15em',
                textTransform: 'uppercase',
                color: 'var(--black)',
                textDecoration: 'none',
                borderBottom: '1px solid var(--black)',
                paddingBottom: '0.25rem',
                transition: 'gap 0.3s ease',
              }}
              onMouseEnter={(e) => ((e.currentTarget as HTMLAnchorElement).style.gap = '1.25rem')}
              onMouseLeave={(e) => ((e.currentTarget as HTMLAnchorElement).style.gap = '0.75rem')}
            >
              View Projects
              <svg width="16" height="8" viewBox="0 0 16 8" fill="none" stroke="currentColor" strokeWidth="1">
                <path d="M0 4h14M10 1l4 3-4 3" />
              </svg>
            </a>
          </div>
        </div>

        {/* Right — cover photo with parallax */}
        <div
          style={{
            position: 'relative',
            overflow: 'hidden',
            background: 'var(--gray-100)',
          }}
        >
          <div
            ref={parallaxRef}
            style={{
              position: 'absolute',
              inset: '-5%',
              transform: `translate(${mousePos.x * 0.3}px, ${mousePos.y * 0.3}px)`,
              transition: 'transform 0.6s cubic-bezier(0.16, 1, 0.3, 1)',
            }}
          >
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={coverPhoto}
              alt="Ayden Pettiette"
              style={{
                width: '100%',
                height: '100%',
                objectFit: 'cover',
                display: 'block',
                filter: 'grayscale(15%)',
              }}
              onError={(e) => {
                const el = e.currentTarget as HTMLImageElement;
                el.style.display = 'none';
              }}
            />
            {/* Overlay gradient */}
            <div
              style={{
                position: 'absolute',
                inset: 0,
                background: 'linear-gradient(to right, rgba(245,243,239,0.25) 0%, transparent 40%)',
              }}
            />
          </div>

          {/* Semester badge */}
          <div
            style={{
              position: 'absolute',
              bottom: '2.5rem',
              right: '2.5rem',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'flex-end',
              gap: '0.25rem',
              zIndex: 2,
            }}
          >
            <span
              style={{
                fontFamily: 'var(--font-mono)',
                fontSize: '0.6rem',
                letterSpacing: '0.15em',
                textTransform: 'uppercase',
                color: 'var(--white)',
                opacity: 0.8,
                textShadow: '0 1px 4px rgba(0,0,0,0.4)',
              }}
            >
              B.Arch Candidate
            </span>
          </div>
        </div>

        {/* Vertical label */}
        <div
          style={{
            position: 'absolute',
            right: '2rem',
            top: '50%',
            transform: 'translateY(-50%) rotate(90deg)',
            transformOrigin: 'center',
            fontFamily: 'var(--font-mono)',
            fontSize: '0.55rem',
            letterSpacing: '0.3em',
            color: 'var(--gray-500)',
            zIndex: 3,
          }}
        >
          ARCHITECTURAL PORTFOLIO
        </div>

        {/* Scroll indicator */}
        <div
          style={{
            position: 'absolute',
            bottom: '2.5rem',
            left: '4rem',
            display: 'flex',
            alignItems: 'center',
            gap: '0.75rem',
            animation: 'fadeInUp 1s ease forwards',
            animationDelay: '1.5s',
            opacity: 0,
          }}
        >
          <div
            style={{
              width: 1,
              height: 40,
              background: 'var(--black)',
              animation: 'scrollPulse 2s ease-in-out infinite',
            }}
          />
          <span
            style={{
              fontFamily: 'var(--font-mono)',
              fontSize: '0.55rem',
              letterSpacing: '0.2em',
              color: 'var(--gray-500)',
              textTransform: 'uppercase',
            }}
          >
            Scroll
          </span>
        </div>
      </section>

      {/* ── MARQUEE ── */}
      <div
        style={{
          borderTop: '1px solid var(--gray-100)',
          borderBottom: '1px solid var(--gray-100)',
          padding: '1rem 0',
          overflow: 'hidden',
          background: 'var(--white)',
        }}
      >
        <div className="marquee-track">
          {[...Array(3)].map((_, i) => (
            <span
              key={i}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '3rem',
                paddingRight: '3rem',
                fontFamily: 'var(--font-mono)',
                fontSize: '0.6rem',
                letterSpacing: '0.2em',
                textTransform: 'uppercase',
                color: 'var(--gray-500)',
                whiteSpace: 'nowrap',
              }}
            >
              <span>Architectural Design</span>
              <MarqueeDot />
              <span>Spatial Studies</span>
              <MarqueeDot />
              <span>Translation of Space — Fall 2024</span>
              <MarqueeDot />
              <span>Riverside Residential — Spring 2025</span>
              <MarqueeDot />
              <span>Bath House — Fall 2025</span>
              <MarqueeDot />
              <span>Mid Rise Complex — Spring 2026</span>
              <MarqueeDot />
              <span>3D Modeling</span>
              <MarqueeDot />
              <span>Texas A&amp;M University</span>
              <MarqueeDot />
            </span>
          ))}
        </div>
      </div>

      <style>{`
        @keyframes scrollPulse {
          0%, 100% { opacity: 0.3; transform: scaleY(1); }
          50% { opacity: 1; transform: scaleY(1.15); }
        }
        @media (max-width: 768px) {
          section { grid-template-columns: 1fr !important; }
          section > div:last-of-type { display: none; }
        }
      `}</style>
    </>
  );
}

function MarqueeDot() {
  return (
    <span
      style={{
        width: 4,
        height: 4,
        borderRadius: '50%',
        background: 'var(--beige-dark)',
        display: 'inline-block',
        flexShrink: 0,
      }}
    />
  );
}
