'use client';
import { useRef, useState, useEffect } from 'react';
import type { Project } from '@/lib/projects';
import { Carousel } from './Carousel';

interface ProjectCardProps {
  project: Project;
  isExpanded: boolean;
  onToggle: () => void;
}

export function ProjectCard({ project, isExpanded, onToggle }: ProjectCardProps) {
  const expandRef = useRef<HTMLDivElement>(null);
  const [expandHeight, setExpandHeight] = useState(0);

  useEffect(() => {
    if (expandRef.current) {
      setExpandHeight(isExpanded ? expandRef.current.scrollHeight : 0);
    }
  }, [isExpanded]);

  const imageItems = project.media.filter((m) => m.type === 'image');
  const glbItems = project.media.filter((m) => m.type === 'glb');
  const coverImage = imageItems[0];

  return (
    <div
      className="project-card"
      style={{
        background: 'var(--white)',
        border: '1px solid var(--gray-100)',
        overflow: 'hidden',
        transition: 'border-color 0.3s ease, box-shadow 0.5s ease, transform 0.5s ease',
        borderColor: isExpanded ? 'var(--beige-dark)' : 'var(--gray-100)',
      }}
    >
      {/* Card header - always visible */}
      <div
        onClick={onToggle}
        data-hover
        style={{
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          cursor: 'pointer',
          position: 'relative',
          overflow: 'hidden',
        }}
      >
        {/* Cover image */}
        <div
          className="img-hover-frame"
          style={{ height: 320, background: 'var(--gray-100)', position: 'relative' }}
        >
          {coverImage ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={coverImage.src}
              alt={coverImage.alt}
              style={{
                width: '100%',
                height: '100%',
                objectFit: 'cover',
                display: 'block',
                filter: 'grayscale(30%)',
                transition: 'transform 0.7s cubic-bezier(0.16,1,0.3,1), filter 0.4s ease',
              }}
              onError={(e) => ((e.currentTarget as HTMLImageElement).style.opacity = '0')}
            />
          ) : (
            <ImagePlaceholder />
          )}
          <div
            style={{
              position: 'absolute',
              inset: 0,
              background: 'linear-gradient(135deg, rgba(0,0,0,0) 60%, rgba(0,0,0,0.2) 100%)',
              pointerEvents: 'none',
            }}
          />
        </div>

        {/* Info panel */}
        <div
          style={{
            padding: '2.5rem 3rem',
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'space-between',
            background: isExpanded ? 'var(--beige-light)' : 'var(--white)',
            transition: 'background 0.4s ease',
            position: 'relative',
          }}
        >
          {/* Semester tag */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <div
              style={{
                width: 6,
                height: 6,
                borderRadius: '50%',
                background: 'var(--beige-dark)',
              }}
            />
            <span className="mono" style={{ color: 'var(--gray-500)', fontSize: '0.6rem' }}>
              {project.semester}
            </span>
          </div>

          {/* Title */}
          <div>
            <h3
              style={{
                fontFamily: 'var(--font-display)',
                fontWeight: 300,
                fontSize: 'clamp(1.8rem, 3vw, 3rem)',
                letterSpacing: '-0.02em',
                lineHeight: 1.05,
                marginBottom: '1rem',
              }}
            >
              {project.title}
            </h3>
            <p
              style={{
                fontFamily: 'var(--font-display)',
                fontWeight: 300,
                fontSize: '1rem',
                color: 'var(--gray-700)',
                lineHeight: 1.7,
                maxWidth: '320px',
              }}
            >
              {project.description}
            </p>
          </div>

          {/* Tags */}
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem', marginTop: '1rem' }}>
            {project.tags.map((tag) => (
              <span
                key={tag}
                style={{
                  fontFamily: 'var(--font-mono)',
                  fontSize: '0.55rem',
                  letterSpacing: '0.1em',
                  textTransform: 'uppercase',
                  color: 'var(--gray-700)',
                  border: '1px solid var(--gray-300)',
                  padding: '0.2rem 0.6rem',
                }}
              >
                {tag}
              </span>
            ))}
            {glbItems.length > 0 && (
              <span
                style={{
                  fontFamily: 'var(--font-mono)',
                  fontSize: '0.55rem',
                  letterSpacing: '0.1em',
                  textTransform: 'uppercase',
                  color: 'var(--white)',
                  background: 'var(--black)',
                  padding: '0.2rem 0.6rem',
                }}
              >
                3D Model
              </span>
            )}
          </div>

          {/* Expand toggle */}
          <div
            style={{
              position: 'absolute',
              bottom: '2rem',
              right: '2.5rem',
              display: 'flex',
              alignItems: 'center',
              gap: '0.5rem',
            }}
          >
            <span className="mono" style={{ color: 'var(--gray-500)', fontSize: '0.55rem' }}>
              {isExpanded ? 'Close' : 'View project'}
            </span>
            <div
              style={{
                width: 28,
                height: 28,
                border: '1px solid var(--gray-300)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                transition: 'transform 0.4s ease, background 0.3s ease, border-color 0.3s ease',
                transform: isExpanded ? 'rotate(45deg)' : 'rotate(0deg)',
                background: isExpanded ? 'var(--black)' : 'transparent',
                borderColor: isExpanded ? 'var(--black)' : 'var(--gray-300)',
              }}
            >
              <svg
                width="12"
                height="12"
                viewBox="0 0 12 12"
                fill="none"
                stroke={isExpanded ? 'var(--white)' : 'var(--black)'}
                strokeWidth="1.5"
              >
                <path d="M6 2v8M2 6h8" />
              </svg>
            </div>
          </div>
        </div>
      </div>

      {/* Expandable content */}
      <div
        ref={expandRef}
        style={{
          height: isExpanded ? 'auto' : 0,
          overflow: 'hidden',
          transition: 'height 0.7s cubic-bezier(0.16, 1, 0.3, 1)',
          opacity: isExpanded ? 1 : 0,
          transitionProperty: 'height, opacity',
          transitionDuration: '0.7s',
        }}
      >
        <div
          style={{
            padding: '3rem',
            borderTop: '1px solid var(--gray-100)',
            background: 'var(--beige-light)',
          }}
        >
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: isExpanded && glbItems.length > 0 ? '1.5fr 1fr' : '1fr',
              gap: '3rem',
            }}
          >
            {/* Image carousel */}
            <div>
              <div style={{ marginBottom: '1.5rem' }}>
                <span className="mono" style={{ color: 'var(--gray-500)', fontSize: '0.6rem' }}>
                  Documentation — {imageItems.length} image{imageItems.length !== 1 ? 's' : ''}
                </span>
              </div>
              <Carousel items={project.media} projectTitle={project.title} />
            </div>

            {/* GLB viewer */}
            {glbItems.length > 0 && (
              <div>
                <div style={{ marginBottom: '1.5rem' }}>
                  <span className="mono" style={{ color: 'var(--gray-500)', fontSize: '0.6rem' }}>
                    3D Model — Interactive
                  </span>
                </div>
                {glbItems.map((glb, i) => (
                  <GlbViewerLazy key={i} src={glb.src} />
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// Lazy-load the GLB viewer only when expanded
function GlbViewerLazy({ src }: { src: string }) {
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setMounted(true), 300);
    return () => clearTimeout(timer);
  }, []);

  if (!mounted)
    return (
      <div
        style={{
          height: 360,
          background: 'var(--gray-900)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        <span className="mono" style={{ color: 'var(--beige)', fontSize: '0.6rem', opacity: 0.5 }}>
          Loading 3D viewer...
        </span>
      </div>
    );

  const { GlbViewer } = require('./GlbViewer');
  return <GlbViewer src={src} height={360} />;
}

function ImagePlaceholder() {
  return (
    <div
      style={{
        width: '100%',
        height: '100%',
        background: 'var(--gray-100)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
      }}
    >
      <svg
        width="48"
        height="48"
        viewBox="0 0 48 48"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        style={{ opacity: 0.2 }}
      >
        <rect x="4" y="4" width="40" height="40" stroke="var(--gray-500)" strokeWidth="1" />
        <path
          d="M4 32l12-10 8 7 8-12 12 16"
          stroke="var(--gray-500)"
          strokeWidth="1"
          fill="none"
        />
        <circle cx="16" cy="16" r="4" stroke="var(--gray-500)" strokeWidth="1" />
      </svg>
    </div>
  );
}
