'use client';
import { useRef, useState } from 'react';
import type { Project } from '@/lib/projects';
import { ScrollReveal } from './ScrollReveal';
import { ProjectCard } from './ProjectCard';

interface ProjectTimelineProps {
  projects: Project[];
}

export function ProjectTimeline({ projects }: ProjectTimelineProps) {
  const [activeProject, setActiveProject] = useState<string | null>(null);

  return (
    <section id="work" style={{ background: 'var(--white)', padding: '8rem 0 6rem' }}>
      {/* Section header */}
      <ScrollReveal>
        <div
          style={{
            padding: '0 4rem',
            marginBottom: '5rem',
            display: 'flex',
            alignItems: 'flex-end',
            justifyContent: 'space-between',
            borderBottom: '1px solid var(--gray-100)',
            paddingBottom: '2rem',
          }}
        >
          <div>
            <span
              className="mono"
              style={{ color: 'var(--gray-500)', display: 'block', marginBottom: '0.5rem' }}
            >
              Selected Work
            </span>
            <h2
              style={{
                fontFamily: 'var(--font-display)',
                fontWeight: 300,
                fontSize: 'clamp(2.5rem, 4vw, 4.5rem)',
                letterSpacing: '-0.02em',
                lineHeight: 1,
              }}
            >
              Projects
            </h2>
          </div>
          <div style={{ textAlign: 'right' }}>
            <span className="mono" style={{ color: 'var(--gray-500)' }}>
              {projects.length} projects
            </span>
            <br />
            <span className="mono" style={{ color: 'var(--gray-500)', fontSize: '0.6rem' }}>
              2024 — 2026
            </span>
          </div>
        </div>
      </ScrollReveal>

      {/* Timeline with projects */}
      <div style={{ padding: '0 4rem', position: 'relative' }}>
        {/* Central timeline line */}
        <div
          style={{
            position: 'absolute',
            left: '4rem',
            top: 0,
            bottom: 0,
            width: '1px',
            background: 'linear-gradient(to bottom, var(--beige-dark), transparent)',
            opacity: 0.4,
          }}
        />

        <div style={{ display: 'flex', flexDirection: 'column', gap: '8rem', paddingLeft: '2rem' }}>
          {projects.map((project, i) => (
            <TimelineEntry
              key={project.id}
              project={project}
              index={i}
              total={projects.length}
              isActive={activeProject === project.id}
              onActivate={() =>
                setActiveProject(activeProject === project.id ? null : project.id)
              }
            />
          ))}
        </div>
      </div>
    </section>
  );
}

function TimelineEntry({
  project,
  index,
  total,
  isActive,
  onActivate,
}: {
  project: Project;
  index: number;
  total: number;
  isActive: boolean;
  onActivate: () => void;
}) {
  const isEven = index % 2 === 0;

  return (
    <ScrollReveal direction={isEven ? 'right' : 'left'} delay={index * 80}>
      <div style={{ position: 'relative' }}>
        {/* Timeline dot */}
        <div
          style={{
            position: 'absolute',
            left: '-2.5rem',
            top: '2rem',
            width: 8,
            height: 8,
            borderRadius: '50%',
            background: isActive ? 'var(--black)' : 'var(--beige-dark)',
            border: '2px solid var(--white)',
            boxShadow: '0 0 0 1px var(--beige-dark)',
            transition: 'background 0.3s ease',
            zIndex: 2,
          }}
        />

        {/* Date label */}
        <div
          style={{
            position: 'absolute',
            left: '-10rem',
            top: '1.75rem',
            textAlign: 'right',
            width: '6rem',
          }}
        >
          <span
            className="mono"
            style={{ color: 'var(--gray-500)', fontSize: '0.55rem', display: 'block' }}
          >
            {project.season}
          </span>
          <span
            className="mono"
            style={{ color: 'var(--beige-dark)', fontSize: '0.55rem', display: 'block' }}
          >
            {project.year}
          </span>
        </div>

        {/* Project number */}
        <div
          style={{
            position: 'absolute',
            right: 0,
            top: '-1rem',
            fontFamily: 'var(--font-display)',
            fontWeight: 300,
            fontSize: '7rem',
            lineHeight: 1,
            color: 'var(--gray-100)',
            userSelect: 'none',
            pointerEvents: 'none',
          }}
        >
          {String(total - index).padStart(2, '0')}
        </div>

        <ProjectCard project={project} isExpanded={isActive} onToggle={onActivate} />
      </div>
    </ScrollReveal>
  );
}
